<?php
require_once __DIR__.'/../../includes/staff/operations.php';require_login();verify_csrf();$pdo=staff_db();$staff=current_staff();$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT p.*,c.name customer_name,c.phone customer_phone,c.email customer_email,c.id customer_id,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) manager_name FROM projects p JOIN customers c ON c.id=p.customer_id LEFT JOIN staff s ON s.id=p.assigned_manager WHERE p.id=?");$q->execute([$id]);$p=$q->fetch();if(!$p){http_response_code(404);exit('Project not found');}
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';
 if($action==='status'){$old=$p['status'];$new=$_POST['status'];$pdo->prepare('UPDATE projects SET status=?,completed_at=IF(?="completed",NOW(),completed_at) WHERE id=?')->execute([$new,$new,$id]);project_activity($pdo,$id,'status_change','Status changed',ucwords(str_replace('_',' ',$old)).' → '.ucwords(str_replace('_',' ',$new)));flash('success','Project status updated.');staff_redirect('staff/pages/project-view.php?id='.$id);}
 if($action==='design_link'){$did=(int)($_POST['design_id']??0);$purpose=$_POST['purpose']??'concept';if($did){$pdo->prepare('INSERT IGNORE INTO project_designs(project_id,design_id,purpose,is_primary,linked_by) VALUES(?,?,?,?,?)')->execute([$id,$did,$purpose,isset($_POST['is_primary'])?1:0,$staff['id']]);project_activity($pdo,$id,'design_linked','Cabinet design linked','Design #'.$did.' linked as '.$purpose);flash('success','Design linked to project.');}staff_redirect('staff/pages/project-view.php?id='.$id);} if($action==='task'){$assigned=$_POST['assigned_to']!==''?(int)$_POST['assigned_to']:null;$due=$_POST['due_date']?str_replace('T',' ',$_POST['due_date']):null;$q=$pdo->prepare('INSERT INTO tasks(title,description,project_id,customer_id,assigned_to,assigned_by,priority,status,due_date) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([trim($_POST['title']),trim($_POST['description'])?:null,$id,$p['customer_id'],$assigned,$staff['id'],$_POST['priority'],'todo',$due]);$tid=(int)$pdo->lastInsertId();notify_staff($pdo,$assigned,'New project task',trim($_POST['title']),'task','task',$tid);project_activity($pdo,$id,'task_created','Task created',trim($_POST['title']));flash('success','Task created.');staff_redirect('staff/pages/project-view.php?id='.$id);}
}
$designs=$pdo->query('SELECT id,design_code,title FROM designs ORDER BY updated_at DESC')->fetchAll();$dq=$pdo->prepare('SELECT pd.*,d.design_code,d.title FROM project_designs pd JOIN designs d ON d.id=pd.design_id WHERE pd.project_id=? ORDER BY pd.is_primary DESC,pd.created_at DESC');$dq->execute([$id]);$linkedDesigns=$dq->fetchAll();$staffRows=$pdo->query("SELECT id,first_name,last_name FROM staff WHERE is_active=1 ORDER BY first_name,last_name")->fetchAll();$mq=$pdo->prepare('SELECT sm.*,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) measured_by_name FROM site_measurements sm LEFT JOIN staff s ON s.id=sm.measured_by WHERE sm.project_id=? ORDER BY sm.measured_at DESC');$mq->execute([$id]);$measurements=$mq->fetchAll();$tq=$pdo->prepare('SELECT t.*,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) assigned_name FROM tasks t LEFT JOIN staff s ON s.id=t.assigned_to WHERE t.project_id=? ORDER BY FIELD(t.status,"in_progress","todo","waiting","completed","cancelled"),t.due_date');$tq->execute([$id]);$tasks=$tq->fetchAll();$aq=$pdo->prepare('SELECT pa.*,CONCAT(s.first_name," ",COALESCE(s.last_name,"")) staff_name FROM project_activity pa LEFT JOIN staff s ON s.id=pa.staff_id WHERE pa.project_id=? ORDER BY pa.created_at DESC LIMIT 40');$aq->execute([$id]);$activity=$aq->fetchAll();$statuses=array_keys(project_statuses());$currentIndex=array_search($p['status'],$statuses,true);$pageTitle=$p['project_code'];require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow"><?= h($p['project_code']) ?></p><h1><?= h($p['name']) ?></h1><p class="muted"><a href="<?= h(ideare_root_url('staff/pages/customer-view.php?id='.$p['customer_id'])) ?>"><?= h($p['customer_name']) ?></a> · <?= h($p['project_type']?:'General project') ?></p></div><div class="actions"><a class="btn" href="<?= h(ideare_root_url('staff/pages/site-measurements.php?project_id='.$id)) ?>">Add measurement</a><a class="btn" href="<?= h(ideare_root_url('staff/pages/projects.php')) ?>">All projects</a></div></div>
<section class="staff-panel"><div class="section-title"><div><p class="eyebrow">Progress</p><h2><?= h(project_statuses()[$p['status']]??$p['status']) ?></h2></div><form method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="status"><select name="status"><?php foreach(project_statuses() as $k=>$v):?><option value="<?= $k ?>" <?= $p['status']===$k?'selected':'' ?>><?= h($v) ?></option><?php endforeach;?></select><button class="btn">Update</button></form></div><div class="progress-track"><?php foreach($statuses as $i=>$s): if(in_array($s,['on_hold','cancelled'],true))continue;?><span class="progress-step <?= $currentIndex!==false&&$i<=$currentIndex?'done':'' ?>" title="<?= h(project_statuses()[$s]) ?>"></span><?php endforeach;?></div><div class="kpi-inline" style="margin-top:18px"><span><small>Manager</small><strong><?= h($p['manager_name']?:'Unassigned') ?></strong></span><span><small>Target</small><strong><?= $p['target_date']?h(date('j M Y',strtotime($p['target_date']))):'—' ?></strong></span><span><small>Value</small><strong><?= money($p['estimated_value']) ?></strong></span></div></section>
<div class="split-grid"><section class="staff-panel"><h2>Create task</h2><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="task"><label>Task<input name="title" required></label><label>Description<textarea name="description"></textarea></label><div class="two"><label>Assign to<select name="assigned_to"><option value="">Unassigned</option><?php foreach($staffRows as $s):?><option value="<?= $s['id'] ?>"><?= h(trim($s['first_name'].' '.$s['last_name'])) ?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><?php foreach(['low','normal','high','urgent'] as $x):?><option value="<?= $x ?>"><?= ucfirst($x) ?></option><?php endforeach;?></select></label></div><label>Deadline<input type="datetime-local" name="due_date"></label><button class="btn primary">Add task</button></form><div class="list"><?php foreach($tasks as $t):?><div class="list-row"><div><b><?= h($t['title']) ?></b><small><?= h($t['assigned_name']?:'Unassigned') ?> · <?= h(str_replace('_',' ',$t['status'])) ?><?= $t['due_date']?' · '.h(date('j M, g:i A',strtotime($t['due_date']))):'' ?></small></div><span class="pill <?= h($t['priority']) ?>"><?= h($t['priority']) ?></span></div><?php endforeach;?></div></section>
<section class="staff-panel"><div class="section-title"><h2>Site measurements</h2><a href="<?= h(ideare_root_url('staff/pages/site-measurements.php?project_id='.$id)) ?>">Open survey</a></div><div class="list"><?php foreach($measurements as $m):?><div class="list-row"><div><b><?= h($m['room_name']) ?></b><small><?= h(date('j M Y, g:i A',strtotime($m['measured_at']))) ?> · <?= h($m['measured_by_name']?:'Unknown') ?></small></div><span><?= $m['wall_a_mm']?h($m['wall_a_mm'].' mm'):'' ?></span></div><?php endforeach;?><?php if(!$measurements):?><p class="muted">No measurements yet.</p><?php endif;?></div></section></div>

<section class="staff-panel"><div class="section-title"><h2>Cabinet designs</h2><a href="<?= h(ideare_root_url('designer/index.php')) ?>">Open configurator ↗</a></div><form method="post" class="mini-form"><?= csrf_field() ?><input type="hidden" name="action" value="design_link"><label>Saved design<select name="design_id" required><option value="">Choose design...</option><?php foreach($designs as $d):?><option value="<?= (int)$d['id'] ?>"><?= h($d['design_code'].' · '.$d['title']) ?></option><?php endforeach;?></select></label><label>Purpose<select name="purpose"><option>concept</option><option>quotation</option><option>approved</option><option>production</option><option>as_built</option></select></label><label><input type="checkbox" name="is_primary"> Primary design</label><button class="btn">Link design</button></form><div class="list"><?php foreach($linkedDesigns as $d):?><div class="list-row"><div><b><?= h($d['design_code'].' · '.$d['title']) ?></b><small><?= h($d['purpose']) ?><?= $d['is_primary']?' · Primary':'' ?></small></div><a class="btn" href="<?= h(ideare_root_url('designer/index.php?design_id='.$d['design_id'])) ?>">Open</a></div><?php endforeach;?><?php if(!$linkedDesigns):?><p class="muted">No configurator design linked yet.</p><?php endif;?></div></section>
<section class="staff-panel"><h2>Project activity</h2><div class="timeline"><?php foreach($activity as $a):?><div class="timeline-item"><b><?= h($a['title']) ?></b><small class="muted"><?= h(date('j M Y, g:i A',strtotime($a['created_at']))) ?> · <?= h($a['staff_name']?:'System') ?></small><?php if($a['description']):?><p><?= h($a['description']) ?></p><?php endif;?></div><?php endforeach;?><?php if(!$activity):?><p class="muted">No activity yet.</p><?php endif;?></div></section></main><?php require __DIR__.'/../../includes/staff/footer.php'; ?>
